def table(df, cols, fmt=None, cls=""):
    fmt=fmt or {}
    h="<div class='tbl'><table><tr>"+"".join(f"<th{' class=num' if c in fmt else ''}>{esc(str(c))}</th>" for c in cols)+"</tr>"
    for _,r in df.iterrows():
        h+="<tr>"+"".join((f"<td class='num'>{fmt[c](r[c])}</td>" if c in fmt else f"<td>{esc(str(r[c]))}</td>") for c in cols)+"</tr>"
    return h+"</table></div>"
